#!/usr/bin/env bash

########################################################################################
# DO NOT EDIT THIS FILE
# Put custom entry point tasks in the file custom_entrypoint.sh

if [ "$1" == "DOCS" ] ; then
  cat /UserDocs.md
  exit 0
fi

# Get the config.
if [ -f /config/service_config.json ]; then
    DEPLOYMENT=$(cat /config/service_config.json | jq -r .deployment)
    NAME=$(cat /config/service_config.json | jq -r .name)
    WEBPORT=$(cat /config/service_config.json | jq -r .specifics.web_port)
    CONFIGURI=$(cat /config/service_config.json | jq -r .config_host_uri)
    CONFIGACCESS=$(cat /config/service_config.json | jq -r .config_access_token)
else
    DEPLOYMENT=$(cat service_config.json | jq -r .deployment)
    NAME=$(cat service_config.json | jq -r .name)
    WEBPORT=$(cat service_config.json | jq -r .specifics.web_port)
    CONFIGURI=$(cat service_config.json | jq -r .config_host_uri)
    CONFIGACCESS=$(cat service_config.json | jq -r .config_access_token)
fi

cd /usr/share/nginx/html/assets/
find . -name "*.js" -exec sed -i "s#__VITE_GINFRA_CONFIG_URI__#${CONFIGURI}#g" {} +
find . -name "*.js" -exec sed -i "s#__VITE_GINFRA_CONFIG_TOKEN__#${CONFIGACCESS}#g" {} +
find . -name "*.js" -exec sed -i "s#__VITE_GINFRA_CONFIG_DEPLOYMENT__#${DEPLOYMENT}#g" {} +
find . -name "*.js" -exec sed -i "s#__VITE_GINFRA_CONFIG_NAME__#${NAME}#g" {} +
find . -name "*.js" -exec sed -i "s#__VITE_GINFRA_CONFIG_PORT__#${PORT}#g" {} +
cd /etc/nginx
find . -name "nginx.conf" -exec sed -i "s#__PORT__#${WEBPORT}#g" {} +

echo "CONFIGURI: ${CONFIGURI}" >> /service/log/start.log
echo "CONFIGACCESS: ${CONFIGACCESS}" >> /service/log/start.log
echo "DEPLOYMENT: ${DEPLOYMENT}" >> /service/log/start.log
echo "NAME: ${NAME}" >> /service/log/start.log
echo "WEBPORT: ${WEBPORT}" >> /service/log/start.log

# Confg
echo "...config" >> /service/log/start.log
cat /etc/nginx/nginx.conf >> /service/log/start.log

# Run nginx
echo "Starting service." >> /service/log/start.log
cd /service
nginx  >> /service/log/nginx_start.log 2>&1 &

# Run control
cp ../service_config.json /service
./ginfra_service.exe /service $1 $2 $3 $4 $5 $6 $7 $8 $9 >> /service/log/start.log 2>&1

